const sessionId = typeof $json.sessionId === 'string' ? $json.sessionId.trim() : '';
const requestId = typeof $json.requestId === 'string' ? $json.requestId.trim() : '';
const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const rawPeriod = typeof $json.period === 'string' ? $json.period.trim() : '';
const force = $json.force === true || String($json.force ?? '').trim().toLowerCase() === 'true';

let error = null;
if (!uuidPattern.test(sessionId) || !uuidPattern.test(requestId)) {
  error = { code: 'INVALID_SESSION', message: 'Starting a review needs a valid conversation and request ID.' };
}

// '' means the default window, 2026-07 means that calendar month, 90d means
// the last ninety days. Anything past 180 days is refused rather than
// silently trimmed: a review of two years of transactions is not what
// somebody meant to ask for, and it would cost accordingly.
let period = '';
if (!error && rawPeriod !== '') {
  if (/^\d{4}-(0[1-9]|1[0-2])$/.test(rawPeriod)) {
    period = rawPeriod;
  } else if (/^\d{1,3}d$/i.test(rawPeriod)) {
    const days = Number(rawPeriod.slice(0, -1));
    if (days < 1 || days > 180) {
      error = { code: 'INVALID_PERIOD', message: 'Ask for up to 180 days at a time, like 90d, or a single month like 2026-07.' };
    } else { period = `${days}d`; }
  } else {
    error = { code: 'INVALID_PERIOD', message: 'A period is either a month like 2026-07 or a number of days like 90d.' };
  }
}

const runId = `run-${Date.now()}-${requestId.slice(0, 8)}`;
return [{ json: {
  valid: error === null, sessionId, requestId, period, force, runId,
  proposedInput: { sessionId, requestId, period, force },
  ...(error ? { response: { ok: false, error } } : {}),
} }];

const input = $('Validate Start Input').first().json;
const rows = $input.all().map((item) => item.json).filter((row) => row && row.runId);

if (!input.valid) {
  return [{ json: { ...input, shouldQueue: false } }];
}

const minutesSince = (value) => {
  const parsed = Date.parse(String(value ?? ''));
  if (Number.isNaN(parsed)) return null;
  return Math.round((Date.now() - parsed) / 60000);
};

// A review takes minutes and spends real money, so one already in flight is
// reported rather than started twice. Nothing here can ask whether that run is
// still alive: a restart, or an execution deleted by hand, leaves exactly the
// same row behind with nobody working on it. So age decides, and the only
// honest number is the one past which n8n has certainly stopped it — the
// executionTimeout on 105, which is 30 minutes. Anything shorter calls a
// working run wreckage and quietly pays for a second one on top of it.
const DEAD_AFTER = 31;

const open = rows
  .filter((row) => String(row.status ?? '') === 'running')
  .map((row) => ({ runId: row.runId, age: minutesSince(row.startedAt) }))
  .filter((entry) => entry.age !== null)
  .sort((a, b) => a.age - b.age);

const live = open.find((entry) => entry.age < DEAD_AFTER) ?? null;

if (live && !input.force) {
  return [{ json: { ...input, shouldQueue: false, response: { ok: true, status: 'already-running',
    runId: live.runId, startedMinutesAgo: live.age,
    message: `A review started ${live.age} minute${live.age === 1 ? '' : 's'} ago and is still going. Reading it back with get_reconciliation_suggestions will show it when it finishes. Say so rather than starting another one, unless they ask you to go again anyway.` } } }];
}

const stale = open.find((entry) => entry.age >= DEAD_AFTER) ?? null;
const replacing = live
  ? { reason: 'asked-again', runId: live.runId, age: live.age }
  : (stale ? { reason: 'interrupted', runId: stale.runId, age: stale.age } : null);

return [{ json: { ...input, shouldQueue: true, replacing } }];

const decided = $('Decide Run').first().json;
const rows = $input.all().map((item) => item.json).filter((row) => row && row.profileId === 'default');
const profile = rows[0] ?? null;

if (!decided.shouldQueue) {
  return [{ json: { ...decided } }];
}

// Unlike the funding search, this one never assumes a profile. A guessed
// always-check-with-me amount decides how much money the agent is willing to
// be confident about, and a guessed coding rule is wrong on every transaction
// from that supplier. Both are silent. So it refuses and asks instead.
if (!profile || !profile.organisationName) {
  return [{ json: { ...decided, shouldQueue: false, response: { ok: false,
    error: { code: 'NO_PROFILE', message: 'There is no bookkeeping profile saved yet.' },
    nextStep: 'Ask the user for three things before starting a review, and save them with set_bookkeeping_profile: what the organisation is called, any coding rules they already follow in their own words, and the dollar amount above which they always want to decide themselves rather than have a code suggested. Without those the review has nothing to reason from.' } } }];
}

return [{ json: { ...decided, profileName: String(profile.organisationName), neverGuessAbove: Number(profile.neverGuessAbove ?? 0) } }];

const raw = $input.first().json ?? {};
const status = Number(raw.statusCode ?? 0);
const body = raw.body ?? {};
const nodeError = String(raw.error?.message ?? raw.error ?? '');
const orgs = Array.isArray(body) ? body : [];
const connected = status === 200 && orgs.length > 0;
return [{ json: { ...$('Check Profile Exists').first().json, xeroConnected: connected,
  xeroProblem: connected ? '' : (status === 401 || status === 403 ? 'needs_reauth'
    : (!status || /credential/i.test(nodeError) ? 'not_connected' : 'unknown')) } }];

const input = $('Read Start Probe').first().json;
const CONNECT_STEPS = "Open n8n at http://localhost:5678 | Go to Credentials and open the one named \"Xero (read-only)\". If it is not there yet it has to be created once, and it needs a Xero developer app first: docs/XERO_RECONCILIATION.md has every click. | Select Connect my account, then grant access. The permission screen should say view, never create or delete.";
const why = {
  not_connected: 'Xero is not connected yet, so there is nothing to review.',
  needs_reauth: 'Xero is set up but is refusing the connection. A Xero refresh token stops working after 60 days without use, so this is usually just a reconnect.',
  unknown: 'Xero did not answer when I checked just now.',
};
return [{ json: { ...input, response: { ok: false,
  error: { code: 'XERO_NOT_CONNECTED', message: why[input.xeroProblem] ?? why.unknown },
  connectSteps: CONNECT_STEPS,
  credentialUrl: 'http://localhost:5678/home/credentials',
  nextStep: 'Do not start a review. Include the exact text http://localhost:5678/home/credentials in your reply: the chat turns that one address into a button to the credential screen, which is where the Xero sign-in window comes from. Read the steps out one at a time. Never ask the user for a Xero password, a verification code, or a client secret.' } } }];

const input = $('Read Start Probe').first().json;
const lines = [];

if (input.replacing && input.replacing.reason === 'interrupted') {
  lines.push(`The review before this one stopped ${input.replacing.age} minutes ago without finishing, which usually means the agent restarted while it was working. Nothing was saved from it, so I have started again.`);
} else if (input.replacing) {
  lines.push('Starting a fresh review now, as you asked.');
}

lines.push('I am going through your Xero transactions now. It takes a few minutes: I read what is still unreconciled, your chart of accounts and how you have coded things before, and work out what each one probably is.');
lines.push('Ask me for it again in a few minutes and I will read it back.');

return [{ json: { ...input, response: {
  ok: true,
  status: 'started',
  runId: input.runId,
  period: input.period || 'the last 90 days',
  restarted: input.replacing ? input.replacing.reason : null,
  message: lines.join(' ')
} } }];

const input = $('Validate Start Input').first().json;
const response = $json.response ?? { ok: false, error: { code: 'TOOL_FAILED', message: 'The tool did not return a result.' } };
return { json: {
  occurredAt: new Date().toISOString(),
  sessionId: input.sessionId,
  requestId: input.requestId,
  toolName: 'start_reconciliation_review',
  proposedInput: JSON.stringify(input.proposedInput ?? {}),
  result: JSON.stringify(response),
  error: response.ok === false ? String(response.error?.message ?? 'Tool failed') : '',
  response
} };

const prepared = $('Prepare Audit').first().json;
const response = { ...prepared.response };
if (!Number.isInteger($json.id)) {
  response.auditWarning = 'The tool result could not be written to the local audit table.';
}
return { json: response };
